animations.text-fade-in:
return new Promise(resolve => {
  gsap.fromTo(targetEl,
    { opacity: 0 },
    { opacity: 1, duration: 0.05, onComplete: resolve }
    );
});

animations.fade-in:
// Fade in using GSAP
return new Promise(resolve => {
  gsap.fromTo(targetEl,
    { opacity: 0 },
    { opacity: 1, duration: 2, onComplete: resolve }
  );
});

animations.scale-in:
// Scale in using GSAP
return new Promise(resolve => {
  gsap.fromTo(targetEl,
    { opacity: 0, scale: 0.5 },
    { opacity: 1, scale: 1, duration: 0.6, ease: 'back.out(1.7)', onComplete: resolve }
  );
});

animations.wipe-left:
// Wipe from right to left using GSAP DrawSVGPlugin
return new Promise(resolve => {
  // Set initial state
  targetEl.style.opacity = '1';

  // Find all drawable elements (line, path, polyline, polygon, circle, rect, ellipse)
  const drawables = targetEl.querySelectorAll('line, path, polyline, polygon, circle, rect, ellipse');

  gsap.fromTo(drawables,
    { drawSVG: '100% 100%' },
    {
      drawSVG: '0% 100%',
      duration: 0.8,
      ease: 'power2.out',
      stagger: 0.1,
      onComplete: resolve
    }
  );
});

